-- 07-player-season-ratings: uploaded workbook snapshot. Run entire file, then Write Changes.
-- Save pending edits and take a backup first. No BEGIN/COMMIT needed in DB Browser.
-- Identical reruns are safe; changed existing records are never overwritten.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_season_7;
CREATE TEMP TABLE afl_season_import_stamp(effective_at TEXT NOT NULL);
CREATE TEMP TABLE afl_season_7_0 AS SELECT id, season_id, player_id, version, offense_position, defense_position, offense_stars, defense_stars, size, strength, speed, stamina, poise, accuracy, arm_strength, read_defense, juke, vision, acceleration, route_running, jump, hands, ball_security, run_blocking, pass_protection, run_stop, tackling, strip, pass_rush, ball_hawk, read_qb, coverage, image_url, image_translate_x, image_translate_y, image_scale, overall_rating, overall_rating_formula_version, effective_from FROM player_season_ratings WHERE 0;
CREATE TEMP TABLE afl_season_7_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_season_7_check BEFORE INSERT ON afl_season_7_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import season (05) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_7_0 i LEFT JOIN players p ON p.id=i.player_id WHERE p.id IS NULL OR p.league_id<>'36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Player IDs missing or belong to another league; import reviewed players first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_7_0 i JOIN player_season_ratings t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.player_id IS NOT i.player_id OR t.version IS NOT i.version OR t.offense_position IS NOT i.offense_position OR t.defense_position IS NOT i.defense_position OR t.offense_stars IS NOT i.offense_stars OR t.defense_stars IS NOT i.defense_stars OR t.size IS NOT i.size OR t.strength IS NOT i.strength OR t.speed IS NOT i.speed OR t.stamina IS NOT i.stamina OR t.poise IS NOT i.poise OR t.accuracy IS NOT i.accuracy OR t.arm_strength IS NOT i.arm_strength OR t.read_defense IS NOT i.read_defense OR t.juke IS NOT i.juke OR t.vision IS NOT i.vision OR t.acceleration IS NOT i.acceleration OR t.route_running IS NOT i.route_running OR t.jump IS NOT i.jump OR t.hands IS NOT i.hands OR t.ball_security IS NOT i.ball_security OR t.run_blocking IS NOT i.run_blocking OR t.pass_protection IS NOT i.pass_protection OR t.run_stop IS NOT i.run_stop OR t.tackling IS NOT i.tackling OR t.strip IS NOT i.strip OR t.pass_rush IS NOT i.pass_rush OR t.ball_hawk IS NOT i.ball_hawk OR t.read_qb IS NOT i.read_qb OR t.coverage IS NOT i.coverage OR t.image_url IS NOT i.image_url OR t.image_translate_x IS NOT i.image_translate_x OR t.image_translate_y IS NOT i.image_translate_y OR t.image_scale IS NOT i.image_scale OR t.overall_rating IS NOT i.overall_rating OR t.overall_rating_formula_version IS NOT i.overall_rating_formula_version OR t.effective_from IS NOT i.effective_from) THEN RAISE(ROLLBACK,'player_season_ratings: existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_7_0 i JOIN player_season_ratings t ON t.season_id=i.season_id AND t.player_id=i.player_id AND t.version=i.version WHERE t.id<>i.id) THEN RAISE(ROLLBACK,'player_season_ratings: natural key belongs to another ID.') END;
END;
DROP TRIGGER afl_season_7_check;
DROP TABLE afl_season_7_guard;
DROP TABLE afl_season_7_0;
DROP TABLE afl_season_import_stamp;
RELEASE SAVEPOINT afl_season_7;
PRAGMA foreign_key_check;
